import re
import json

def deidentify_phi(text):
    def extract_names(text):
        pattern = r'\b(Mr|Mrs|Ms|Dr|Prof)\.?\s([A-Za-z]+)\s([A-Za-z]+)\b'
        return [(m.start(), m.end(), 'NAME', m.group(2) + ' ' + m.group(3)) for m in re.finditer(pattern, text)]

    def extract_dates(text):
        pattern = r'\b(\d{1,2} [A-Za-z]+ \d{4}\b)'
        return [(m.start(), m.end(), 'DATE', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_locations(text):
        pattern = r'\b(Limerick|Ireland|Dublin|Dept\. of Foriegn Affairs)\b'
        return [(m.start(), m.end(), 'LOCATION', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_phone_numbers(text):
        pattern = r'\b(\d{3}[-\.\s]??\d{3}[-\.\s]??\d{4}|\(\d{3}\)\s*\d{3}[-\.\s]??\d{4})\b'
        return [(m.start(), m.end(), 'PHONE', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_emails(text):
        pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
        return [(m.start(), m.end(), 'EMAIL', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_ids(text):
        pattern = r'\b(\d{9,11})\b'
        return [(m.start(), m.end(), 'ID', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_other_phi(text):
        pattern = r'\b(Protocol|Article|Section|Aricle|Conventions|Goverment|Goverment|State|Sate|Court|Agent|Agent|Dept|No\.|No)\b'
        return [(m.start(), m.end(), 'OTHER', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_age(text):
        pattern = r'\b(\d{1,3})\b'
        return [(m.start(), m.end(), 'AGE', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_urls(text):
        pattern = r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+'
        return [(m.start(), m.end(), 'URL', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_ips(text):
        pattern = r'\b(25[0-5]|2[0-4][0-9]|[0-1]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[0-1]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[0-1]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[0-1]?[0-9][0-9]?)\b'
        return [(m.start(), m.end(), 'IP', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_biometric_ids(text):
        pattern = r'\b(photograph|photo|picture|image|biometric|fingerprint|face|iris|voice|signature)\b'
        return [(m.start(), m.end(), 'BIOMETRIC_ID', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_vehicle_ids(text):
        pattern = r'\b(license|VIN|plate|registration)\b'
        return [(m.start(), m.end(), 'VEHICLE_ID', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_device_ids(text):
        pattern = r'\b(serial|IMEI|MAC|device)\b'
        return [(m.start(), m.end(), 'DEVICE_ID', m.group(0)) for m in re.finditer(pattern, text)]

    def extract_phi(text):
