import re
import json

def deidentify_phi(text):
    def extract_name(text):
        return re.findall(r'\b[A-Z][a-z]+ [A-Z][a-z]+\b', text)

    def extract_date(text):
        return re.findall(r'\b\d{1,2} [A-Za-z]+ \d{4}\b', text)

    def extract_location(text):
        return re.findall(r'\b[A-Z][a-z]+, [A-Z]{2}\b', text)

    def extract_phone(text):
        return re.findall(r'\b\d{3}[-\.\s]??\d{3}[-\.\s]??\d{4}\b', text)

    def extract_email(text):
        return re.findall(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', text)

    def extract_id(text):
        return re.findall(r'\b\d{9}\b', text)

    def extract_age(text):
        return re.findall(r'\b\d{1,3}\b', text)

    def extract_other(text):
        return re.findall(r'\b[A-Z][a-z]+ [A-Z][a-z]+\b', text)  # Other PHI includes names, but we already have a specific function for names

    def extract_phi(text):
        names = extract_name(text)
        dates = extract_date(text)
        locations = extract_location(text)
        phones = extract_phone(text)
        emails = extract_email(text)
        ids = extract_id(text)
        ages = extract_age(text)
        others = extract_other(text)

        phi = []
        for name in names:
            phi.append({
                'start': text.find(name),
                'end': text.find(name) + len(name),
                'label': 'NAME',
                'text': name
            })
        for date in dates:
            phi.append({
                'start': text.find(date),
                'end': text.find(date) + len(date),
                'label': 'DATE',
                'text': date
            })
        for location in locations:
            phi.append({
                'start': text.find(location),
                'end': text.find(location) + len(location),
                'label': 'LOCATION',
                'text': location
            })
        for phone in phones:
            phi.append({
                'start': text.find(phone),
                'end': text.find(phone) + len(phone),
                'label': 'PHONE',
                'text': phone
            })
        for email in emails:
            phi.append({
                'start': text.find(email),
                'end': text.find(email) + len(email),
                'label': 'EMAIL',
                'text': email
            })
        for id in ids:
            phi.append({
                'start': text.find(id),
                'end': text.find(id) + len(id),
                'label': 'ID',
                'text': id
            })
        for age in ages:
            phi.append({
                'start': text.find(age),
                'end': text.find(age) + len(age),
                'label': 'AGE',
                'text': age
            })
        for other in others:
            phi.append({
                'start': text.find(other),
                'end': text.find(other) + len(other),
                'label': 'OTHER',
                'text': other
            })

        return phi

    phi = extract_phi(text)
    return json.dumps({'spans': phi})

